const AICreativeAssistant = () => {
  const [prompt, setPrompt] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Hello! I am Lumina AI, your creative consultant. Need inspiration for your next project?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!prompt.trim() || isLoading) return;

    const userMsg = prompt;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setPrompt('');
    setIsLoading(true);

    const response = await generateCreativeResponse(userMsg);
    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setIsLoading(false);
  };

  return (
    <section id="ai" className="py-32 relative">
      <div className="max-w-4xl mx-auto px-6">
        <div className="glass p-8 md:p-12 rounded-[3rem] shadow-2xl overflow-hidden relative">
          <div className="absolute top-0 right-0 p-8">
            <Sparkles className="text-indigo-500 opacity-20" size={120} />
          </div>

          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-8">
              <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center shadow-lg shadow-indigo-500/50">
                <Zap size={20} className="text-white" />
              </div>
              <div>
                <h2 className="text-2xl font-bold">Lumina AI Assistant</h2>
                <p className="text-sm text-slate-400">Powered by Gemini Pro</p>
              </div>
            </div>

            <div className="h-80 overflow-y-auto mb-8 space-y-6 pr-4 custom-scrollbar">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-4 rounded-2xl ${
                    m.role === 'user' 
                      ? 'bg-indigo-600 text-white' 
                      : 'bg-slate-800/50 text-slate-200 border border-slate-700'
                  }`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="bg-slate-800/50 p-4 rounded-2xl border border-slate-700 flex gap-1">
                    <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce" />
                    <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce delay-100" />
                    <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce delay-200" />
                  </div>
                </div>
              )}
            </div>

            <div className="relative">
              <input 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask me for a design concept..."
                className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-6 py-4 focus:ring-2 focus:ring-indigo-500 outline-none transition-all pr-16"
              />
              <button 
                onClick={handleSend}
                disabled={isLoading}
                className="absolute right-3 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center hover:bg-indigo-700 transition-colors disabled:opacity-50"
              >
                <Send size={18} />
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

