const MatchmakerSection = () => {
  const [currentStep, setCurrentStep] = useState(0);
  const [answers, setAnswers] = useState<Record<number, string>>({});

  const progress = ((currentStep + 1) / QUESTIONS.length) * 100;

  const handleNext = () => {
    if (currentStep < QUESTIONS.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrev = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const selectOption = (optionId: string) => {
    setAnswers({ ...answers, [currentStep]: optionId });
  };

  return (
    <section id="matchmaker" className="py-24 px-6 lg:px-24 bg-slate-50 min-h-screen">
      <div className="max-w-3xl mx-auto">
        <div className="bg-white rounded-[2rem] p-8 lg:p-12 card-shadow">
          <h2 className="text-3xl font-black text-center text-[#000080] mb-8">Tennis Level Matchmaker</h2>

          {/* Progress Bar */}
          <div className="w-full h-3 bg-slate-100 rounded-full mb-12 overflow-hidden">
            <motion.div 
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              className="h-full bg-[#4c8bf5] rounded-full"
            />
          </div>

          <AnimatePresence mode="wait">
            <motion.div
              key={currentStep}
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              className="space-y-8"
            >
              <h3 className="text-xl font-black text-[#000080] mb-6">
                {QUESTIONS[currentStep].question}
              </h3>

              <div className="space-y-4">
                {QUESTIONS[currentStep].options.map(opt => (
                  <button 
                    key={opt.id}
                    onClick={() => selectOption(opt.id)}
                    className={`w-full p-6 text-left rounded-2xl border-2 transition-all ${answers[currentStep] === opt.id ? 'bg-[#4c8bf5] border-[#4c8bf5] text-white shadow-xl shadow-[#4c8bf5]/20' : 'bg-white border-slate-100 text-[#000080] hover:border-[#4c8bf5]/30'}`}
                  >
                    <span className={`inline-block px-3 py-1 rounded-md text-[10px] font-black uppercase mb-3 ${answers[currentStep] === opt.id ? 'bg-white text-[#4c8bf5]' : 'bg-[#4c8bf5] text-white'}`}>
                      {opt.tag}
                    </span>
                    <p className="font-bold text-lg leading-tight mb-2">{opt.label}</p>
                    <p className={`text-sm ${answers[currentStep] === opt.id ? 'text-white/80' : 'text-slate-500'}`}>{opt.description}</p>
                  </button>
                ))}
              </div>
            </motion.div>
          </AnimatePresence>

          <div className="flex justify-between items-center mt-12 pt-8 border-t border-slate-100">
            <button 
              onClick={handlePrev}
              disabled={currentStep === 0}
              className={`text-lg font-bold transition-all ${currentStep === 0 ? 'opacity-20 cursor-not-allowed' : 'text-[#4c8bf5] hover:opacity-70'}`}
            >
              Previous
            </button>
            <button 
              onClick={handleNext}
              className="px-10 py-4 bg-[#4c8bf5] hover:bg-[#3b7ae4] text-white rounded-xl font-bold transition-all shadow-lg active:scale-95"
            >
              {currentStep === QUESTIONS.length - 1 ? 'Finish' : 'Next'}
            </button>
          </div>
        </div>
      </div>
    </section>
  );
};

