  }

  return (
    <section id="matchmaker" className="py-24 px-6 lg:px-24 bg-slate-50 min-h-screen">
      <div className="max-w-3xl mx-auto">
        <div className="bg-white rounded-[2rem] p-8 lg:p-12 card-shadow">
