export const MobileNav = () => {
  const [isOpen, setIsOpen] = useState(false);
  const { scrollY } = useScroll();
  const headerHeight = useTransform(scrollY, [0, 100], ["8rem", "4rem"]);
  const logoSize = useTransform(scrollY, [0, 100], ["8rem", "4rem"]);
  const scrollTo = (id: string) => { document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' }); setIsOpen(false); };

  return (
    <div className="lg:hidden fixed top-0 left-0 w-full z-[100]">
      <motion.div style={{ height: headerHeight }} className="relative flex items-center justify-center bg-[#000080] text-white shadow-lg px-6 overflow-visible">
        <motion.div style={{ width: logoSize, height: logoSize }} className="flex items-center justify-center cursor-pointer" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>
          <img src={ASSETS.logo} alt="Logo" className="w-full h-full object-contain" />
        </motion.div>
        <button onClick={() => setIsOpen(!isOpen)} className="absolute right-6 p-2 z-[110]">{isOpen ? <X size={28} /> : <Menu size={28} />}</button>
      </motion.div>
      <AnimatePresence>
        {isOpen && (
          <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} className="bg-[#000080] p-8 text-white flex flex-col gap-8 shadow-2xl absolute top-full left-0 w-full z-[105]">
            {NAV_ITEMS.map(item => (
              <button key={item.id} onClick={() => scrollTo(item.id)} className="text-2xl font-bold flex items-center gap-4">
                <span className="text-[#4c8bf5]">{item.icon}</span> {item.label}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

