      const { scrollTop, offsetHeight } = containerRef.current;
      setActiveIdx(Math.round(scrollTop / offsetHeight));
    }
  };

  const navigateTo = (idx: number) => {
    containerRef.current?.scrollTo({ top: idx * containerRef.current.offsetHeight, behavior: 'smooth' });
  };

  return (
    <section id="about-section" className="relative lg:h-[calc(100vh-5rem)] overflow-hidden bg-white">
      <div ref={containerRef} onScroll={handleScroll} className="h-full overflow-y-auto snap-y snap-mandatory scroll-smooth no-scrollbar">
